function formatSeconds(total: number) {
  const minutes = Math.floor(total / 60).toString().padStart(2, "0");
  const seconds = (total % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
}

function CalendarPanel({ onDate }: { onDate: () => void }) {
  const days = ["月", "火", "水", "木", "金", "土", "日"];
  return <section className="glass-card overflow-hidden rounded-[28px] p-4">
    <div className="mb-3 flex items-center justify-between">
      <div><p className="eyebrow">learning calendar</p><h2 className="mt-1 text-lg font-bold">2026年 8月</h2></div>
      <button onClick={onDate} className="rounded-xl bg-white/8 px-3 py-2 text-xs text-slate-200 transition hover:bg-white/12">詳細を見る</button>
    </div>
    <div className="grid grid-cols-7 gap-y-1 text-center text-[10px] text-slate-400">{days.map(d => <span key={d}>{d}</span>)}</div>
    <div className="mt-1 grid grid-cols-7 gap-1">
      {Array.from({ length: 35 }, (_, index) => {
        const day = index - 4;
        const active = [2, 3, 6, 7, 9, 10, 13, 15, 16, 17, 19].includes(day);
        const current = day === 20;
        return <button key={index} onClick={onDate} disabled={day < 1 || day > 31} className={`relative mx-auto grid h-8 w-8 place-items-center rounded-full text-xs transition ${current ? "bg-cyan-300 font-bold text-slate-950 shadow-[0_0_22px_rgba(109,232,221,.45)]" : active ? "bg-white/10 text-slate-50 hover:bg-white/16" : "text-slate-500"}`}>
          {day > 0 && day <= 31 ? day : ""}{active && !current && <i className="absolute bottom-1 h-1 w-1 rounded-full bg-cyan-300" />}
        </button>;
      })}
    </div>
    <div className="mt-4 flex items-center gap-3 rounded-2xl bg-slate-950/30 px-3 py-2 text-xs text-slate-300"><Flame className="h-4 w-4 text-orange-300" /><span>今月の学習日数 <b className="ml-1 text-white">11日</b></span><span className="ml-auto font-mono text-cyan-200">+03:25</span></div>
  </section>;
}

