function QrScannerModal({ onDetected, onClose }: { onDetected: (value: string) => void; onClose: () => void }) {
  const videoRef = useRef<HTMLVideoElement>(null); const [message,setMessage]=useState("カメラを起動しています…");
  useEffect(()=>{let stream:MediaStream|undefined;let timer:number|undefined;let closed=false;const boot=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw new Error("CAMERA_UNAVAILABLE");stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});if(closed){stream.getTracks().forEach(track=>track.stop());return;}if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play();}const Detector=(window as Window & { BarcodeDetector?: new (options:{formats:string[]})=>{detect:(source:unknown)=>Promise<Array<{rawValue?:string}>>} }).BarcodeDetector;if(!Detector){setMessage("このブラウザはQRの自動読取に対応していません。教室コードを手入力してください。");return;}const detector=new Detector({formats:["qr_code"]});setMessage("QRコードを枠内に写してください。");timer=window.setInterval(async()=>{if(!videoRef.current)return;try{const found=await detector.detect(videoRef.current);const raw=found[0]?.rawValue?.trim();if(raw){const code=raw.replace(/^STUDYVERSE:/i,"").trim();onDetected(code);}}catch{/* フレーム読取失敗時は次の周期で再試行 */}},450);}catch(error){setMessage(error instanceof DOMException&&error.name==="NotAllowedError"?"カメラの利用が許可されませんでした。教室コードを手入力してください。":"カメラを開始できませんでした。教室コードを手入力してください。");}};void boot();return()=>{closed=true;if(timer)window.clearInterval(timer);stream?.getTracks().forEach(track=>track.stop());};},[onDetected]);
  return <div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/80 p-4 sm:place-items-center"><section className="glass-card w-full max-w-md rounded-[28px] p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">qr classroom code</p><h2 className="mt-1 text-lg font-bold">教室コードを読み取る</h2></div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl bg-white/8" aria-label="閉じる"><X className="h-4 w-4"/></button></div><div className="mt-5 overflow-hidden rounded-2xl border border-cyan-200/20 bg-slate-950/45"><video ref={videoRef} muted playsInline className="aspect-video w-full object-cover"/><div className="relative -mt-[55%] mx-auto h-40 w-40 rounded-2xl border-2 border-cyan-200/80 shadow-[0_0_0_9999px_rgba(2,6,23,.2)]"/></div><p className="mt-5 text-center text-xs leading-5 text-slate-300">{message}</p><button onClick={onClose} className="mt-4 w-full rounded-xl border border-white/12 py-3 text-sm font-bold text-slate-200">手入力に戻る</button></section></div>;
}

function AdminBootstrap({ onClose }: { onClose: () => void }) {
  const auth=trpc.siteAdmin.me.useQuery(); const login=trpc.siteAdmin.login.useMutation(); const createRoom=trpc.classroom.rooms.create.useMutation(); const createOwner=trpc.classroom.members.createPinAccount.useMutation(); const utils=trpc.useUtils(); const [password,setPassword]=useState(""); const [name,setName]=useState(""); const [code,setCode]=useState(""); const [owner,setOwner]=useState(""); const [pin,setPin]=useState("");
  const signIn=async(event:React.FormEvent)=>{event.preventDefault();try{await login.mutateAsync({password});setPassword("");await utils.siteAdmin.me.invalidate();toast.success("全体管理者として認証しました。");}catch(error){toast.error(error instanceof Error?error.message:"認証できませんでした。");}};
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(!/^[A-Z0-9-]{3,32}$/.test(code.trim().toUpperCase()))return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");if(!/^[0-9]{4}$/.test(pin))return toast.error("オーナーPINは4桁の数字で入力してください。");try{const room=await createRoom.mutateAsync({name:name.trim(),code:code.trim().toUpperCase()});if(!room.id)throw new Error("教室を作成できませんでした。");await createOwner.mutateAsync({classroomId:room.id,displayName:owner.trim(),pin,classroomRole:"owner"});toast.success("教室とオーナーPINを作成しました。PINは安全な場所で管理してください。");onClose();}catch(error){toast.error(error instanceof Error?error.message:"初期設定を保存できませんでした。");}};
  if(auth.isLoading)return <Modal title="管理者の初期設定" onClose={onClose}><p className="py-6 text-sm text-slate-300">管理者情報を確認しています…</p></Modal>;
  if(auth.data?.role!=="admin")return <Modal title="全体管理者ログイン" onClose={onClose}><p className="mt-4 text-sm leading-6 text-slate-300">このサイト固有の全体管理者パスワードを入力してください。外部アカウントとの連携は不要です。</p><form onSubmit={signIn}><label className="mt-5 block text-xs font-bold text-slate-200">全体管理者パスワード<input autoFocus required type="password" value={password} onChange={event=>setPassword(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="パスワードを入力"/></label><button disabled={login.isPending} className="mt-4 w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{login.isPending?"認証しています…":"全体管理者として認証"}</button></form></Modal>;
  return <Modal title="教室とオーナーPINを作成" onClose={onClose}><form onSubmit={submit} className="mt-4 space-y-3"><label className="block text-xs font-bold text-slate-200">教室名<input required value={name} onChange={event=>setName(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：東南学習教室"/></label><label className="block text-xs font-bold text-slate-200">教室コード<input required value={code} onChange={event=>setCode(event.target.value.toUpperCase())} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：STAR-2026"/></label><label className="block text-xs font-bold text-slate-200">オーナー表示名<input required value={owner} onChange={event=>setOwner(event.target.value)} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-sm" placeholder="例：教室管理者"/></label><label className="block text-xs font-bold text-slate-200">オーナーPIN<input required inputMode="numeric" maxLength={4} value={pin} onChange={event=>setPin(event.target.value.replace(/\D/g,""))} className="mt-2 w-full rounded-xl border border-white/12 bg-slate-950/35 px-3 py-3 text-center font-mono text-lg tracking-[.4em]" placeholder="••••"/></label><p className="text-[10px] leading-4 text-slate-400">PINは保存後に表示できません。作成直後に安全な経路で管理者へ共有してください。</p><button disabled={createRoom.isPending||createOwner.isPending} className="w-full rounded-xl bg-cyan-300 py-3 text-sm font-bold text-slate-950 disabled:opacity-60">{createRoom.isPending||createOwner.isPending?"作成しています…":"教室とPINを作成"}</button></form></Modal>;
}

function LoginGate({ onEnter }: { onEnter: (pin: string, classroom: string) => Promise<void> }) {
  const [pin, setPin] = useState("");
  const [classroom, setClassroom] = useState("");
  const [showHelp, setShowHelp] = useState(false);
  const [scanning,setScanning]=useState(() => new URLSearchParams(window.location.search).get("preview") === "qr"); const [submitting,setSubmitting]=useState(false); const [adminSetup,setAdminSetup]=useState(() => new URLSearchParams(window.location.search).get("preview") === "admin-setup");
  const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!isValidPin(pin)) return toast.error("PINは4桁の数字で入力してください。"); if (!isValidClassroomCode(classroom)) return toast.error("教室コードは英数字とハイフンで3〜32文字にしてください。");setSubmitting(true);try{await onEnter(pin, normalizeClassroomCode(classroom));}finally{setSubmitting(false);} };
  return <main className="sky-shell relative grid min-h-screen place-items-center overflow-hidden px-5 py-10"><div className="star-field" /><div className="absolute -left-24 top-8 h-64 w-64 rounded-full bg-cyan-300/10 blur-3xl" /><motion.section initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .45 }} className="glass-card relative w-full max-w-[430px] rounded-[32px] p-6 sm:p-8">
    <div className="mb-8 flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-gradient-to-br from-cyan-200 to-violet-400 text-slate-950 shadow-[0_0_25px_rgba(122,232,226,.35)]"><Sparkles className="h-5 w-5" /></div><div><p className="text-xl font-extrabold tracking-[-.04em]">StudyVerse</p><p className="font-mono text-[10px] uppercase tracking-[.18em] text-cyan-200">learning orbit</p></div></div><MoonStar className="h-5 w-5 text-slate-400" /></div>
    <div><p className="eyebrow">entry portal</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.05em]">学びを、続ける軌道へ。</h1><p className="mt-3 text-sm leading-6 text-slate-300">4桁PINと教室コードで、あなたの学習空間を開きます。</p></div>
    <form onSubmit={submit} className="mt-7 space-y-5"><label className="block"><span className="mb-2 block text-xs font-semibold text-slate-200">4桁 PIN</span><div className="relative"><KeyRound className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-cyan-200" /><input autoFocus inputMode="numeric" maxLength={4} value={pin} onChange={e => setPin(e.target.value.replace(/\D/g, ""))} placeholder="• • • •" className="w-full rounded-2xl border border-white/12 bg-slate-950/35 py-3.5 pl-11 pr-4 text-center font-mono text-xl tracking-[.45em] text-white placeholder:tracking-[.3em] placeholder:text-slate-600" /></div></label>
      <label className="block"><span className="mb-2 block text-xs font-semibold text-slate-200">教室コード</span><div className="relative"><GraduationCap className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-violet-200" /><input value={classroom} onChange={e => setClassroom(e.target.value.toUpperCase())} placeholder="例：STAR-2026" className="w-full rounded-2xl border border-white/12 bg-slate-950/35 py-3.5 pl-11 pr-12 text-sm text-white placeholder:text-slate-500" /><button type="button" aria-label="教室コードを読み取る" onClick={() => setScanning(true)} className="absolute right-2 top-1/2 grid h-9 w-9 -translate-y-1/2 place-items-center rounded-xl text-cyan-200 transition hover:bg-white/10"><ScanLine className="h-5 w-5" /></button></div></label>
      <button disabled={submitting} type="submit" className="glow-pulse w-full rounded-2xl bg-gradient-to-r from-cyan-300 via-teal-200 to-cyan-300 py-4 text-sm font-extrabold text-slate-950 transition hover:brightness-110 active:scale-[.98] disabled:opacity-60">{submitting?"認証しています…":"学習空間をひらく"} <ArrowRight className="ml-1 inline h-4 w-4" /></button></form>
    <button onClick={() => setShowHelp(!showHelp)} className="mt-5 w-full text-center text-xs text-slate-400 underline-offset-4 hover:text-cyan-200 hover:underline">教室コードが分からない場合</button>{showHelp && <p className="mt-3 rounded-xl bg-white/6 p-3 text-xs leading-5 text-slate-300">先生から共有された教室コードを確認してください。コードがない場合は、先生または管理者に発行を依頼してください。</p>}<button onClick={()=>setAdminSetup(true)} className="mt-3 w-full text-center text-xs font-bold text-violet-200 hover:underline">管理者の初期設定</button>
    <p className="mt-8 text-center font-mono text-[9px] leading-4 tracking-wide text-slate-500">PINは4桁の数字のみを受け付けます。<br />同じPINでも教室が異なれば別の学習空間として扱います。</p>{scanning&&<QrScannerModal onClose={()=>setScanning(false)} onDetected={value=>{if(!/^[A-Za-z0-9-]{3,32}$/.test(value)){toast.error("QRコード内の教室コード形式が正しくありません。");return;}setClassroom(value.toUpperCase());setScanning(false);toast.success("教室コードを読み取りました。");}}/>}{adminSetup&&<AdminBootstrap onClose={()=>setAdminSetup(false)}/>}
  </motion.section></main>;
}

